const input = $input.first().json.body;

const locale = input.locale || 'fr';
const LANG_MAP = {
  en:'English', fr:'French', es:'Spanish', ar:'Arabic',
  pt:'Portuguese', de:'German', it:'Italian', nl:'Dutch', tr:'Turkish'
};
const language = LANG_MAP[locale] || 'French';

const consultant = input.consultant_profile || {};
const cName = consultant.full_name || [consultant.first_name, consultant.last_name].filter(Boolean).join(' ') || 'Consultant';
const cRole = consultant.job_title || 'Expert consultant';
const cBio  = consultant.bio || '';
const cSpec = consultant.specialties || '';
const cSite = consultant.website || '';

const agent = input.active_agent || null;
const agentActive = !!(agent?.name);
const aiConfig = input.ai_config || {};
const customSys = !agentActive ? (aiConfig.systemPrompt || '') : '';

let persona;
if (agentActive && agent.base_prompt) {
  persona = agent.base_prompt + (agent.description ? '\n(Agent: ' + agent.description + ')' : '');
} else if (agentActive) {
  persona = 'Agent: ' + agent.name + (agent.description ? '. ' + agent.description : '');
} else if (customSys) {
  persona = customSys;
} else {
  persona = `You are acting on behalf of ${cName}, a ${cRole}. Design a qualification form that perfectly reflects their expertise, vocabulary, and ideal client profile.`;
}

const tone       = aiConfig.tone || 'professional';
const complexity = aiConfig.questionComplexity || 'intermediate';
const nbQ        = parseInt(aiConfig.numberOfQuestions) || 10;
const extraCtx   = aiConfig.questionContext || '';

const prompt =
`<s>
You are an elite UX Form Architect and B2B lead qualification specialist.
Your mission: generate highly optimized, consultant-specific qualification forms that maximize prospect engagement and lead quality.
Reason internally before generating. Then output ONLY the JSON.
</s>

<persona>
${persona}
</persona>

<output_language>
ALL user-visible text (form_title, form_description, labels, placeholders, options, thank_you) MUST be written in ${language}.
Instructions and reasoning are in English.
</output_language>

<rules>
FORM QUALITY:
1. Generate EXCLUSIVELY for professional consultants — generic one-size-fits-all forms are STRICTLY FORBIDDEN.
2. Every question must reflect the consultant's domain, vocabulary, and ideal prospect profile.
3. Generate the COMPLETE structure: form_title + form_description + questions array + thank_you_title + thank_you_description.

FIELD TYPES:
4. Allowed types: text | textarea | select | radio | checkbox | email | phone | url | number | date | file | section
5. "section" groups related questions — MUST have sectionTitle AND empty label. Maximum 3 sections.
6. select / radio / checkbox MUST include "options" array: 2-5 mutually exclusive choices, max 5 words each.
7. Do NOT add email or phone fields unless the consultant explicitly requests them.

QUALIFICATION STRATEGY:
8. Questions must qualify the prospect across: need clarity → context → budget signal → urgency → readiness.
9. FOOT-IN-THE-DOOR PRINCIPLE: Place personal info fields (name, email, phone) ONLY at the very end.
   Start with easy, problem-focused questions. Build commitment progressively.
10. Target: ${nbQ} questions (sections excluded). Minimum 8.

UX COPY LIMITS (strictly enforced):
11. form_title: MAX 6 words — clear, action-oriented, benefit-focused
12. form_description: MAX 30 words — value proposition + expectation setting
13. question label: MAX 10 words — plain conversational language, no jargon
14. thank_you_title: MAX 4 words (e.g., "Request received", "You're all set")
15. thank_you_description: MAX 30 words — state the EXACT next step and timeframe
</rules>

<output_format>
Output ONLY valid raw JSON. No markdown fences. No preamble. Just the JSON.

{
  "form_title": "string — max 6 words",
  "form_description": "string — max 30 words",
  "questions": [
    { "type": "section",   "sectionTitle": "Section name in ${language}", "label": "", "required": false },
    { "type": "radio",     "label": "Question in ${language}?", "options": ["Option A", "Option B", "Option C"], "required": true },
    { "type": "textarea",  "label": "Open question?", "placeholder": "Describe your situation...", "required": false },
    { "type": "text",      "label": "Full name",  "placeholder": "Jane Smith", "required": true },
    { "type": "email",     "label": "Email address", "placeholder": "you@company.com", "required": true }
  ],
  "thank_you_title": "string — max 4 words",
  "thank_you_description": "string — max 30 words with next step and timeframe"
}
</output_format>

<context>
Consultant: ${cName} — ${cRole}
${cBio  ? 'Bio: ' + cBio + '\n' : ''}${cSpec ? 'Specialties: ' + cSpec + '\n' : ''}${cSite ? 'Website: ' + cSite + '\n' : ''}
Tone: ${tone} | Complexity: ${complexity}${extraCtx ? ' | Context: ' + extraCtx : ''}

Consultant request: "${input.prompt || 'Generate a qualification form for my consulting practice'}"
Current form title in builder: "${input.form_title || 'Untitled'}"
</context>`;

return [{
  json: {
    ...$input.first().json,
    generated_prompt: prompt,
    _debug: { agentActive, language, nbQ }
  }
}];

const response = $input.first().json;
let content = response.text || response.message?.content || JSON.stringify(response);

content = content.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
const fs = content.indexOf('```');
if (fs !== -1) {
  const fe = content.lastIndexOf('```');
  if (fe > fs) {
    const al = content.indexOf('\n', fs);
    content = content.substring(al > -1 ? al + 1 : fs + 3, fe).trim();
  }
}

const s = content.indexOf('{'); const e = content.lastIndexOf('}');
let parsed;
try {
  parsed = JSON.parse(s !== -1 && e > s ? content.substring(s, e + 1) : content);
} catch(err) {
  throw new Error('PARSE_FAILED: Gemini returned invalid JSON. Raw: ' + content.substring(0, 300));
}

if (!Array.isArray(parsed.questions) || parsed.questions.length === 0) {
  throw new Error('SCHEMA_ERROR: questions array missing or empty');
}

const ALLOWED = ['text','textarea','select','radio','checkbox','email','phone','url','number','date','file','section'];

const questions = (parsed.questions || []).map((q, i) => {
  const type = ALLOWED.includes(q.type) ? q.type : 'text';
  if (type === 'section') {
    const title = q.sectionTitle || q.label || ('Section ' + (i + 1));
    return { type: 'section', label: title, sectionTitle: title, required: false };
  }
  const base = {
    type,
    label: q.label || ('Question ' + (i + 1)),
    placeholder: q.placeholder || '',
    required: q.required !== false
  };
  if (['select','radio','checkbox'].includes(type)) {
    base.options = Array.isArray(q.options) && q.options.length > 0 ? q.options : ['Option 1', 'Option 2'];
  }
  return base;
});

return [{ json: {
  success: true,
  questions,
  form_title:            (parsed.form_title            || '').trim(),
  form_description:      (parsed.form_description      || '').trim(),
  thank_you_title:       (parsed.thank_you_title       || '').trim(),
  thank_you_description: (parsed.thank_you_description || '').trim()
}}];
